<script>
(() => {
  "use strict";

  const canvas = document.getElementById("coin-hero");
  const ctx = canvas.getContext("2d", { alpha: false });
  const faceCanvas = document.createElement("canvas");
  faceCanvas.width = faceCanvas.height = 640;
  const fctx = faceCanvas.getContext("2d");

  let running = true;
  let raf = 0;
  let start = performance.now();
  const TAU = Math.PI * 2;

  const norm = v => {
    const d = Math.hypot(v.x, v.y, v.z) || 1;
    return {x:v.x/d,y:v.y/d,z:v.z/d};
  };
  const light = norm({x:-0.48,y:-0.58,z:0.78});

  function arcText(g, text, cx, cy, radius, startAngle, endAngle, inward) {
    const chars = [...text];
    g.save();
    g.fillStyle = "rgba(57,35,10,.78)";
    g.font = "700 21px ui-sans-serif,system-ui,sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    const span = endAngle - startAngle;
    chars.forEach((ch,i) => {
      const a = startAngle + span * (chars.length === 1 ? .5 : i/(chars.length-1));
      g.save();
      g.translate(cx + Math.cos(a)*radius, cy + Math.sin(a)*radius);
      g.rotate(a + (inward ? -Math.PI/2 : Math.PI/2));
      g.fillText(ch,0,0);
      g.restore();
    });
    g.restore();
  }

  function makeFace(front, t, facing) {
    const g = fctx, S = faceCanvas.width, c=S/2, r=302;
    g.clearRect(0,0,S,S);

    g.save();
    g.beginPath();
    g.arc(c,c,r,0,TAU);
    g.clip();

    const base = g.createRadialGradient(c-115,c-135,15,c,c,r*1.14);
    base.addColorStop(0,"#fff0aa");
    base.addColorStop(.17,"#d8aa4c");
    base.addColorStop(.45,"#8a5a20");
    base.addColorStop(.69,"#d7a94c");
    base.addColorStop(.88,"#6b4217");
    base.addColorStop(1,"#d4a34a");
    g.fillStyle=base;
    g.fillRect(0,0,S,S);

    for(let i=0;i<24;i++){
      const rr=35+i*12.5;
      g.strokeStyle=i%2 ? "rgba(255,236,164,.035)" : "rgba(47,24,3,.04)";
      g.lineWidth=7;
      g.beginPath();g.arc(c,c,rr,0,TAU);g.stroke();
    }

    const rim = g.createRadialGradient(c,c,r*.73,c,c,r);
    rim.addColorStop(0,"rgba(0,0,0,0)");
    rim.addColorStop(.78,"rgba(255,232,151,.10)");
    rim.addColorStop(.82,"rgba(45,22,2,.55)");
    rim.addColorStop(.86,"rgba(248,211,112,.72)");
    rim.addColorStop(.9,"rgba(76,42,8,.7)");
    rim.addColorStop(.96,"rgba(248,211,112,.5)");
    rim.addColorStop(1,"rgba(37,20,4,.85)");
    g.fillStyle=rim;
    g.fillRect(0,0,S,S);

    g.strokeStyle="rgba(54,29,5,.8)";
    g.lineWidth=5;
    g.beginPath();g.arc(c,c,242,0,TAU);g.stroke();
    g.strokeStyle="rgba(255,229,142,.55)";
    g.lineWidth=2;
    g.beginPath();g.arc(c-1,c-2,236,0,TAU);g.stroke();

    if(front){
      arcText(g,"WASTEDTOKEN",c,c,264,Math.PI*1.13,Math.PI*1.87,false);
      arcText(g,"PRIVATE MINT • MMXXV",c,c,261,Math.PI*.16,Math.PI*.84,true);

      g.save();
      g.translate(c,c-4);
      g.beginPath();
      g.moveTo(0,-151);g.lineTo(121,-83);g.lineTo(101,81);
      g.quadraticCurveTo(0,166,-101,81);g.lineTo(-121,-83);g.closePath();
      g.fillStyle="rgba(70,38,6,.56)";
      g.fill();

      g.translate(-4,-5);
      g.beginPath();
      g.moveTo(0,-151);g.lineTo(121,-83);g.lineTo(101,81);
      g.quadraticCurveTo(0,166,-101,81);g.lineTo(-121,-83);g.closePath();
      const sh=g.createLinearGradient(-90,-120,90,120);
      sh.addColorStop(0,"#f2d27a");sh.addColorStop(.45,"#b77a29");sh.addColorStop(1,"#6e4213");
      g.fillStyle=sh;g.fill();
      g.strokeStyle="rgba(255,238,166,.72)";g.lineWidth=5;g.stroke();

      g.textAlign="center";g.textBaseline="middle";
      g.font="900 124px Georgia,serif";
      g.fillStyle="rgba(61,31,4,.72)";g.fillText("WT",5,9);
      g.fillStyle="#d6a94e";g.fillText("WT",0,3);
      g.strokeStyle="rgba(255,239,166,.6)";g.lineWidth=2;g.strokeText("WT",-1,1);
      g.restore();

      g.fillStyle="rgba(55,28,4,.74)";
      g.beginPath();
      for(let i=0;i<24;i++){
        const a=i/24*TAU, rr=i%2?217:223;
        const x=c+Math.cos(a)*rr,y=c+Math.sin(a)*rr;
        g.moveTo(x+4,y);g.arc(x,y,4,0,TAU);
      }
      g.fill();
    } else {
      arcText(g,"WASTEDTOKEN RESERVE",c,c,265,Math.PI*1.12,Math.PI*1.88,false);
      arcText(g,"ONE VERIFIED ARTIFACT",c,c,261,Math.PI*.16,Math.PI*.84,true);

      g.textAlign="center";g.textBaseline="middle";
      g.font="900 104px ui-sans-serif,system-ui,sans-serif";
      g.fillStyle="rgba(54,29,5,.8)";g.fillText("10,000",c+5,c-32+7);
      const numGrad=g.createLinearGradient(c-180,c-100,c+180,c+40);
      numGrad.addColorStop(0,"#f7db86");numGrad.addColorStop(.45,"#a96e23");numGrad.addColorStop(.75,"#f0c663");numGrad.addColorStop(1,"#744315");
      g.fillStyle=numGrad;g.fillText("10,000",c,c-32);
      g.strokeStyle="rgba(255,239,169,.65)";g.lineWidth=2;g.strokeText("10,000",c-1,c-34);

      g.font="900 47px ui-sans-serif,system-ui,sans-serif";
      g.letterSpacing="8px";
      g.fillStyle="rgba(57,29,3,.8)";g.fillText("TOKENS",c+3,c+73);
      g.fillStyle="#d9ad50";g.fillText("TOKENS",c,c+68);

      g.strokeStyle="rgba(64,33,4,.72)";g.lineWidth=6;
      g.beginPath();g.moveTo(c-160,c+118);g.lineTo(c+160,c+118);g.stroke();
      g.strokeStyle="rgba(255,232,148,.5)";g.lineWidth=2;
      g.beginPath();g.moveTo(c-158,c+113);g.lineTo(c+158,c+113);g.stroke();
    }

    const stripePos = c + Math.sin(t*TAU)*205;
    const spec = g.createLinearGradient(stripePos-100,0,stripePos+100,S);
    spec.addColorStop(0,"rgba(255,255,230,0)");
    spec.addColorStop(.42,"rgba(255,249,206,.03)");
    spec.addColorStop(.5,"rgba(255,255,237,.56)");
    spec.addColorStop(.58,"rgba(255,244,184,.08)");
    spec.addColorStop(1,"rgba(255,255,255,0)");
    g.globalCompositeOperation="screen";
    g.fillStyle=spec;
    g.fillRect(0,0,S,S);

    const directional=Math.max(-.2, facing.x*light.x+facing.y*light.y+facing.z*light.z);
    g.globalCompositeOperation="source-over";
    g.fillStyle=`rgba(20,10,2,${Math.max(0,.18-directional*.12)})`;
    g.fillRect(0,0,S,S);
    g.restore();
  }

  function project(p,cx,cy,scale=1){
    return {x:cx+p.x*scale,y:cy+p.y*scale,z:p.z};
  }

  function render(t){
    t=((Number(t)||0)%1+1)%1;
    const W=canvas.width,H=canvas.height,cx=W/2,cy=H/2;
    const bg=ctx.createRadialGradient(cx,cy-20,20,cx,cy,460);
    bg.addColorStop(0,"#182024");
    bg.addColorStop(.48,"#101518");
    bg.addColorStop(1,"#080b0d");
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

    const yaw=TAU*t;
    const pitch=TAU*2*t;
    const sy=Math.sin(yaw),cyaw=Math.cos(yaw);
    const sp=Math.sin(pitch),cp=Math.cos(pitch);

    const u={x:cyaw,y:0,z:-sy};
    const v={x:sy*sp,y:cp,z:cyaw*sp};
    const n={x:sy*cp,y:-sp,z:cyaw*cp};

    const R=246, half=29, segments=112;
    const quads=[];

    for(let i=0;i<segments;i++){
      const a0=i/segments*TAU,a1=(i+1)/segments*TAU;
      const p0={
        x:Math.cos(a0)*u.x+Math.sin(a0)*v.x,
        y:Math.cos(a0)*u.y+Math.sin(a0)*v.y,
        z:Math.cos(a0)*u.z+Math.sin(a0)*v.z
      };
      const p1={
        x:Math.cos(a1)*u.x+Math.sin(a1)*v.x,
        y:Math.cos(a1)*u.y+Math.sin(a1)*v.y,
        z:Math.cos(a1)*u.z+Math.sin(a1)*v.z
      };
      const pts=[
        {x:R*p0.x-half*n.x,y:R*p0.y-half*n.y,z:R*p0.z-half*n.z},
        {x:R*p1.x-half*n.x,y:R*p1.y-half*n.y,z:R*p1.z-half*n.z},
        {x:R*p1.x+half*n.x,y:R*p1.y+half*n.y,z:R*p1.z+half*n.z},
        {x:R*p0.x+half*n.x,y:R*p0.y+half*n.y,z:R*p0.z+half*n.z}
      ];
      const mid=norm({x:p0.x+p1.x,y:p0.y+p1.y,z:p0.z+p1.z});
      const dl=Math.max(0,mid.x*light.x+mid.y*light.y+mid.z*light.z);
      quads.push({pts,z:pts.reduce((s,p)=>s+p.z,0)/4,dl,i});
    }

    quads.sort((a,b)=>a.z-b.z);
    for(const q of quads){
      const ridge=q.i%2===0;
      const lum=30+q.dl*145+(ridge?22:0);
      ctx.beginPath();
      q.pts.forEach((p,j)=>{
        const pp=project(p,cx,cy);
        j?ctx.lineTo(pp.x,pp.y):ctx.moveTo(pp.x,pp.y);
      });
      ctx.closePath();
      ctx.fillStyle=`rgb(${Math.round(lum*1.18)},${Math.round(lum*.78)},${Math.round(lum*.31)})`;
      ctx.fill();
      ctx.strokeStyle=ridge?"rgba(255,225,140,.22)":"rgba(25,11,1,.35)";
      ctx.lineWidth=1.2;
      ctx.stroke();
    }

    const front=n.z>=0;
    const sign=front?1:-1;
    const facing={x:n.x*sign,y:n.y*sign,z:n.z*sign};
    makeFace(front,t,facing);

    const bx=front?u.x:-u.x, by=front?u.y:-u.y;
    const vx=v.x,vy=v.y;
    const fc={x:cx+sign*half*n.x,y:cy+sign*half*n.y};
    const S=faceCanvas.width;
    ctx.save();
    ctx.setTransform(
      2*R*bx/S,2*R*by/S,
      2*R*vx/S,2*R*vy/S,
      fc.x-R*bx-R*vx,
      fc.y-R*by-R*vy
    );
    ctx.drawImage(faceCanvas,0,0);
    ctx.restore();

    const edgeLight=Math.max(0,facing.x*light.x+facing.y*light.y+facing.z*light.z);
    ctx.save();
    ctx.globalCompositeOperation="screen";
    ctx.globalAlpha=.07+.1*edgeLight;
    ctx.beginPath();
    ctx.ellipse(fc.x,fc.y,R*Math.hypot(bx,by),R*Math.hypot(vx,vy),
      Math.atan2(by,bx),0,TAU);
    ctx.strokeStyle="#fff3bd";
    ctx.lineWidth=2;
    ctx.stroke();
    ctx.restore();
  }

  function frame(now){
    if(!running)return;
    render(((now-start)%12000)/12000);
    raf=requestAnimationFrame(frame);
  }

  window.demo={
    canvas,
    setTime(t){ render(Math.max(0,Math.min(1,Number(t)||0))); },
    pause(){
      running=false;
      if(raf)cancelAnimationFrame(raf);
