  function drawEdition(canvasEl,name,index){
    const g=canvasEl.getContext("2d"),W=canvasEl.width,c=W/2,r=157;
    const p=palettes[name];
    g.clearRect(0,0,W,W);

    const halo=g.createRadialGradient(c,c,20,c,c,205);
    halo.addColorStop(0,name==="black"?"rgba(112,142,151,.14)":"rgba(225,183,92,.12)");
    halo.addColorStop(1,"rgba(0,0,0,0)");
    g.fillStyle=halo;g.fillRect(0,0,W,W);

    g.save();
    g.translate(0,8);
    g.beginPath();g.ellipse(c,c+151,130,22,0,0,TAU);
    g.fillStyle="rgba(0,0,0,.42)";g.fill();
    g.restore();

    g.beginPath();g.arc(c,c,r+10,0,TAU);
    const edge=g.createLinearGradient(c-r,c-r,c+r,c+r);
    edge.addColorStop(0,p[2]);edge.addColorStop(.25,p[0]);edge.addColorStop(.52,p[1]);edge.addColorStop(.76,p[0]);edge.addColorStop(1,p[2]);
    g.fillStyle=edge;g.fill();

    for(let i=0;i<72;i++){
      const a=i/72*TAU;
      g.strokeStyle=i%2?p[2]:p[0];
      g.globalAlpha=.6;
      g.lineWidth=2;
      g.beginPath();
      g.moveTo(c+Math.cos(a)*(r+2),c+Math.sin(a)*(r+2));
      g.lineTo(c+Math.cos(a)*(r+10),c+Math.sin(a)*(r+10));
