    g.beginPath();g.arc(c,c,r,0,TAU);
    const face=g.createRadialGradient(c-58,c-72,8,c,c,r*1.15);
    face.addColorStop(0,p[0]);face.addColorStop(.36,p[1]);face.addColorStop(.7,p[2]);face.addColorStop(.88,p[1]);face.addColorStop(1,p[0]);
    g.fillStyle=face;g.fill();

