    g.beginPath();g.arc(c,c,r-20,0,TAU);g.stroke();
    g.strokeStyle=p[0];g.globalAlpha=.55;g.lineWidth=2;
    g.beginPath();g.arc(c-1,c-1,r-25,0,TAU);g.stroke();
