    g.fillText(String(index+1).padStart(2,"0")+" / PHYSICAL PROOF",c,c+126);

    g.save();
    g.beginPath();g.arc(c,c,r,0,TAU);g.clip();
    const shine=g.createLinearGradient(55,45,325,360);
    shine.addColorStop(0,"rgba(255,255,255,0)");
